-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the perfsand capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- advanced: some graded figure(s) printed; section 3 pick B (strip)
--
-- THE LABEL:
--   Open book, in part: some of the figures this capstone grades can be read in
--   this tier's lessons or on a panel as it opens, so for now those check that
--   you can find, read and report them correctly. A later update takes them out
--   of the lessons and panels.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- perfsand / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'perfsand' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book perfsand refused: perfsand/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '62b02d599b5860369be90d007ea70718' and fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb then 'old'
              when md5(prompt) = '79d9f8e3c894368cb67c7bb5ed21b5dd' and fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'perfsand' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book perfsand refused: perfsand/advanced matches neither its published form (prompt md5 62b02d599b5860369be90d007ea70718) nor its W1 form (prompt md5 79d9f8e3c894368cb67c7bb5ed21b5dd), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' then
    raise notice 'w1 open-book perfsand: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book perfsand refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Six values. THE SAND is the Associate capstone sieve, cumulative retained in microns: 560 at 2, 400 at 7, 280 at 19, 200 at 36, 140 at 54, 100 at 70, 70 at 83, 50 at 92 and 38 at 96. THE INTERVAL runs from 2200 to 2320 m measured depth, screened at a step of 25 m, as an OPEN HOLE cavity, with a strength boost factor of 1.15. Report: (1) the MINIMUM of the Saucier gravel band in metres; (2) the GAUGE MARGIN in metres, meaning the largest permissible gauge less the gauge actually selected; (3) the CRITICAL FLOWING PRESSURE at the governing station in pascals; (4) the GOVERNING critical drawdown pressure in pascals; (5) the critical drawdown pressure at the BOTTOM station in pascals; and (6) the boost factor at which the governing margin is exactly ZERO. Traps. The Saucier band is a multiplier on D50 and NOT on D10, and using the coarse percentile oversizes the pack by a factor of well over two. The gauge series is DISCRETE, so field 2 is a leftover and not a design choice, and it is the bound less the SELECTED gauge rather than the bound less the gravel size. The step does NOT divide the interval: 120 m at 25 m gives 2200, 2225, 2250, 2275, 2300 and then a CLAMPED bottom at 2320, which is SIX rows and not five, and the sixth exists only because the engine walks to the interval bottom rather than to the last whole step before it. Fields 4 and 5 are DIFFERENT numbers and field 4 is the SMALLER: on this interval the TOP station governs, so a learner who assumes the deepest row is the worst one reports field 5 twice. Field 6 is a search and not a formula. Free checks: field 5 must EXCEED field 4, since the governing value is a minimum over the rows; field 6 must be BELOW the applied 1.15, because at 1.15 the interval still has margin; and field 1 must equal five times the Associate tier D50 exactly.',
           fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb
     where app_slug = 'perfsand' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book perfsand refused: perfsand/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '79d9f8e3c894368cb67c7bb5ed21b5dd' and fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb) from public.academy_capstones where app_slug = 'perfsand' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book perfsand refused: perfsand/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book perfsand: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
